sp_page.css:
body,
.sp-page-root,
.container,
.container-fluid {

background: linear-gradient(
180deg,
#F3F6FB 0%,
#EDF2F8 100%
);

padding-top:0 !important;

}


/* REMOVE VERTICAL SPACE BETWEEN PAGE ROWS */

.sp-row{

margin:10px !important;

padding:0 !important;

}


/* CONTROL COLUMN SPACING */

.sp-column{

padding-top:0 !important;

padding-bottom:0 !important;

margin-top:0 !important;

margin-bottom:10px !important;

}


/* REMOVE WIDGET STACK GAPS */

.sp-widget{

margin-bottom:10px !important;

}


/* REMOVE EXTRA ROW SPACING */

.row{

margin-top:0 !important;

margin-bottom:0 !important;

}


/* HERO → FOOTER VISUAL GAP */

.hero-wrapper{

margin-bottom:-14px !important;

}


/* FOOTER POSITION */

.footer-wrap{

margin-top:0 !important;

}
